import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.ieP-ZwyM.js";const s="/RustCMS/v/0.14.0/img/operations/mail-test.webp",p=JSON.parse('{"title":"Running mail","description":"","frontmatter":{},"headers":[],"relativePath":"operations/mail.md","filePath":"operations/mail.md","lastUpdated":1793170150000}'),n={name:"operations/mail.md"};function r(d,e,l,c,h,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="running-mail" tabindex="-1">Running mail <a class="header-anchor" href="#running-mail" aria-label="Permalink to &quot;Running mail&quot;">​</a></h1><p>What to check and what to do when mail does not arrive. See <a href="./../digging-deeper/mail.html">Mail</a> for the configuration.</p><h2 id="checking-the-server" tabindex="-1">Checking the server <a class="header-anchor" href="#checking-the-server" aria-label="Permalink to &quot;Checking the server&quot;">​</a></h2><p><img src="'+s+'" alt="Settings → Mail: Send test mail and its result"><em>The demo application: Settings → Mail, a test mail refused with an error code.</em></p><p><strong>Settings → Mail → <em>Send test mail</em></strong> sends now with the saved settings and shows the error code (<code>smtp_auth</code>, <code>smtp_tls</code>, <code>mail_policy</code>…). It is recorded in the audit log (<code>mail.test_sent</code>, the address masked).</p><p>In production with <code>driver = &quot;smtp&quot;</code> and the server set in the panel, <code>mail.allowed_hosts</code> must list the servers mail may go to (or <code>*</code>): the application does not start otherwise.</p><h2 id="when-something-fails" tabindex="-1">When something fails <a class="header-anchor" href="#when-something-fails" aria-label="Permalink to &quot;When something fails&quot;">​</a></h2><ul><li><strong>The server is down</strong>: mails wait in the queue and are retried with backoff, then fail: <code>mail.send</code> and invitations 8 runs (about 20 minutes of waits), password resets 5 runs (about 2½ minutes; the user asks again). Sending time and a busy queue add to these. Once it is back, list the failed jobs (<code>rustcms queue:failed</code>, or the Queue page filtered on failed) and retry the mail jobs by id (<code>rustcms queue:retry &lt;id&gt;</code>). Do not use <code>queue:retry --all</code>: it also runs every other failed job again (imports, your own jobs, interrupted Run now tasks), whose effects may already have happened. A mail that timed out may have been delivered: check before retrying it.</li><li><strong>A refused message, a bad template, a refused password</strong>: fails at once (not retried). Fix, then retry.</li><li><strong>The password cannot be decrypted</strong> (<code>mail_settings_unreadable</code>): usually <code>APP_KEY</code> changed without the old key in <code>APP_PREVIOUS_KEYS</code>. Put the old key back in <code>APP_PREVIOUS_KEYS</code> on every process and restart; enter the password again only if no key you hold opens it (<a href="./app-key.html">Rotating APP_KEY</a>).</li><li><strong>Too many mails</strong> (<code>smtp_throttled</code>): each process sends at most a burst of <code>mail.max_per_minute</code> (60), then about <code>max_per_minute / 60</code> per second; a send waits up to a minute for its turn before failing with this code, and the job is retried later.</li><li><strong>Nothing is sent at all</strong>: check that a queue worker runs somewhere (<a href="./queue.html">Running the queue</a>), that <code>driver</code> is not <code>disabled</code> or <code>log</code>, and that a sender address is set (<code>mail_not_configured</code> otherwise).</li></ul><h2 id="reset-links-and-invitations" tabindex="-1">Reset links and invitations <a class="header-anchor" href="#reset-links-and-invitations" aria-label="Permalink to &quot;Reset links and invitations&quot;">​</a></h2><ul><li><strong>Reset links</strong>: a link works <code>auth.password_reset_minutes</code> (60) and once. A request waits at most 15 minutes in the queue: an older one fails as <code>expired_before_sent</code> and is not sent. A user gets a new link at most once per <code>auth.reset_cooldown_secs</code> (60). Users ask again from the sign-in page.</li><li><strong>Invitations</strong>: links work <code>auth.invitation_days</code> (7, at most 30); <em>Send the invitation again</em> on the user page makes a new one (the old one stops working).</li></ul><h2 id="several-instances" tabindex="-1">Several instances <a class="header-anchor" href="#several-instances" aria-label="Permalink to &quot;Several instances&quot;">​</a></h2><p><code>mail.max_per_minute</code> counts per process (a token bucket: a burst of <code>max_per_minute</code>, then a steady rate of <code>max_per_minute</code> per minute): with several web and worker processes, the total rate and burst are that many times higher. Set it so the total stays within your provider&#39;s limit.</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><ul><li>Mailpit (<code>docker compose up mailpit</code>) catches every mail: SMTP on port 51025, UI on <a href="http://localhost:58025" target="_blank" rel="noreferrer">http://localhost:58025</a>; a second one with STARTTLS (<code>mailpit-tls</code>) listens on 51026. Allow its port and plain SMTP: <code>allowed_ports = [51025]</code>, <code>allow_insecure = true</code>, <code>encryption = &quot;none&quot;</code> without a user name (<a href="./../digging-deeper/mail.html#testing">Mail</a>).</li><li>Or the <code>log</code> driver with <code>RUSTCMS_MAIL__LOG_BODY=true</code> (only with <code>APP_ENV=local</code>) prints them. It still needs a sender address: saved on <strong>Settings → Mail</strong>, or <code>source = &quot;config&quot;</code> with <code>[smtp] from_address</code>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../digging-deeper/mail.html">Mail</a></li><li><a href="./queue.html">Running the queue</a></li><li><a href="./../reference/error-codes.html#mail">Error codes</a></li></ul>',16)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
